function totalNumbers(digits) {
  // Go through every even number from 100 to 998 and check that the digits it needs are available.
  const have = new Array(10).fill(0);
  for (const d of digits) have[d]++;
  let total = 0;
  for (let number = 100; number < 1000; number += 2) {
    const need = new Array(10).fill(0);
    for (const ch of String(number)) need[Number(ch)]++;
    if (need.every((count, d) => count <= have[d])) total++;
  }
  return total;
}

