function generate(rand, size) {
  const n = size === 'large' ? 10 : 3 + Math.floor(rand() * 8);
  // Digits come from a random pool of allowed values, so repeats, zeros and all-odd inputs all occur.
  const pool = [];
  for (let d = 0; d <= 9; d++) if (rand() < 0.4) pool.push(d);
  if (pool.length === 0) pool.push(Math.floor(rand() * 10));
  return [Array.from({ length: n }, () => pool[Math.floor(rand() * pool.length)])];
}
